package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Caps the new owner's {@link Owner#getMembershipLevel() membershipLevel} at one above the current
 * maximum membershipLevel among their existing household members — owners sharing the same deterministic
 * {@link Household#id(String, String) household id} (same last name and postcode). The cap is persisted
 * on the owner (see {@link Owner#getMembershipLevelCap()}) so the ceiling is honoured on later reads.
 *
 * <p>Runs before {@link SaveOwner}, so the owner being created is not yet among the household members and
 * does not cap itself. With no existing household member, no cap is applied.
 */
public class CapMembershipLevel {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String householdId = Household.id(owner.getLastName(), owner.getPostcode());
        List<Owner> members = new ArrayList<>();
        for (Owner existing : ownerRepository.findAll()) {
            if (householdId.equals(Household.id(existing.getLastName(), existing.getPostcode()))) {
                members.add(existing);
            }
        }
        if (members.isEmpty()) {
            return; // no existing household member -> no cap
        }
        int maxLevel = 0;
        for (Owner member : members) {
            member.setHouseholdSize(members.size());
            maxLevel = Math.max(maxLevel, member.getMembershipLevel());
        }
        owner.setMembershipLevelCap(maxLevel + 1);
    }
}

